/**
 * Application tables (Phase 2 foundation + stubs for later phases).
 *
 * Auth/org tables (users, sessions, accounts, verifications, organizations,
 * members, invitations) live in ./auth-schema.ts and are generated by the
 * Better Auth CLI (`npx @better-auth/cli generate`) so their shape always
 * matches exactly what the Better Auth Drizzle adapter expects. Do not
 * hand-edit that file's table definitions; re-run the generator instead.
 */
import {
  pgTable,
  text,
  timestamp,
  uuid,
  jsonb,
  varchar,
  integer,
} from "drizzle-orm/pg-core";
import { organizations } from "./auth-schema";

/**
 * Websites a tenant has registered for crawling/SEO auditing.
 *
 * Ownership verification (Phase 3): `verificationToken` is generated when
 * the website row is created; the user is shown it and asked to either
 * publish it as a `<meta name="seo-platform-verification" content="...">`
 * tag on their homepage or as a `_seo-platform-verify` DNS TXT record.
 * `verifiedAt`/`verificationMethod` are set only once our own code has
 * actually fetched the page (or looked up the TXT record) and found the
 * token — see src/lib/ownership-verification.ts. This is a real, if
 * basic, check: it is NOT a checkbox the user can tick themselves.
 *
 * Per spec, a manual one-off audit is allowed on an unverified site (see
 * INTEGRATION_ARCHITECTURE.md for the rationale); verification is only
 * required before scheduled/extensive scans, which are out of scope until
 * Phase 5.
 */
export const websites = pgTable("websites", {
  id: uuid("id").primaryKey().defaultRandom(),
  organizationId: text("organization_id")
    .notNull()
    .references(() => organizations.id, { onDelete: "cascade" }),
  url: text("url").notNull(),
  verificationToken: text("verification_token").notNull(),
  verificationMethod: varchar("verification_method", { length: 16 }),
  verifiedAt: timestamp("verified_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * A single crawl run against a website.
 * `options` carries the crawl-time configuration (maxPages, maxDepth,
 * jsRendering, and the test-only SSRF allowlist override — see
 * crawl-safety.ts) so a job is fully reproducible from its stored row.
 */
export const crawlJobs = pgTable("crawl_jobs", {
  id: uuid("id").primaryKey().defaultRandom(),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  status: varchar("status", { length: 32 }).notNull().default("pending"),
  options: jsonb("options").notNull().default({}),
  error: text("error"),
  startedAt: timestamp("started_at", { withTimezone: true }),
  finishedAt: timestamp("finished_at", { withTimezone: true }),
});

/**
 * An individual technical-SEO issue surfaced by a crawl job.
 *
 * Normalized finding schema (see docs/INTEGRATION_ARCHITECTURE.md): every
 * finding, whether it comes directly from siteone-crawler's analyzer or
 * from our own supplementary rule-engine pass, is mapped into this exact
 * shape so the dashboard/report layer never needs to know which engine
 * produced it. `sourceEngine` + `category` together say which: e.g.
 * sourceEngine="siteone-crawler", category="broken_link" vs.
 * sourceEngine="supplementary-rules", category="duplicate_title".
 */
export const findings = pgTable("findings", {
  id: uuid("id").primaryKey().defaultRandom(),
  crawlJobId: uuid("crawl_job_id")
    .notNull()
    .references(() => crawlJobs.id, { onDelete: "cascade" }),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  sourceEngine: varchar("source_engine", { length: 32 }).notNull(),
  url: text("url").notNull(),
  canonicalUrl: text("canonical_url"),
  httpStatus: integer("http_status"),
  severity: varchar("severity", { length: 16 }).notNull(),
  category: varchar("category", { length: 64 }).notNull(),
  title: text("title").notNull(),
  description: text("description").notNull().default(""),
  evidence: jsonb("evidence").notNull().default({}),
  discoveredAt: timestamp("discovered_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * AI-generated recommendations for a crawl job (Phase 4).
 *
 * Hard requirements this table enforces/supports (see
 * docs/REPORTING.md and src/lib/ai/recommendation-engine.ts):
 *  - `findingIds` is a JSON array of real `findings.id` UUIDs this
 *    recommendation is grounded in. It is populated by OUR code from
 *    the actual finding rows handed to the engine, never by parsing
 *    anything the AI model emitted — so a recommendation can never cite
 *    a finding that doesn't exist, even if the model hallucinates.
 *  - `priority` is derived from the grounding finding(s)' own severity
 *    plus a small, documented category-impact heuristic (see
 *    computePriority in recommendation-engine.ts) — never a fabricated
 *    score.
 *  - `body` is model-generated prose when an AI provider was available,
 *    or a deterministic template when it was not — `metadata.generatedBy`
 *    says which, so nothing here is presented as AI-verified when it
 *    wasn't.
 */
export const aiRecommendations = pgTable("ai_recommendations", {
  id: uuid("id").primaryKey().defaultRandom(),
  crawlJobId: uuid("crawl_job_id")
    .notNull()
    .references(() => crawlJobs.id, { onDelete: "cascade" }),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  /**
   * finding_explanation | title_meta_suggestion | internal_linking |
   * structured_data | dev_task | audit_summary
   */
  kind: varchar("kind", { length: 32 }).notNull(),
  /** Real `findings.id` UUIDs this recommendation is grounded in. Never empty. */
  findingIds: jsonb("finding_ids").notNull().default([]),
  /** critical | high | medium | low — derived, see computePriority(). Null only for audit_summary. */
  priority: varchar("priority", { length: 16 }),
  title: text("title").notNull(),
  body: text("body").notNull(),
  /** { generatedBy: "ollama"|"template-fallback", model?, suggestedTitle?, suggestedMetaDescription?, ... } */
  metadata: jsonb("metadata").notNull().default({}),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * A generated report artifact for a website (Phase 4).
 *
 * One `crawl_jobs` row can have up to 4 report rows (one per format);
 * `filePath` is relative to the app's report storage root
 * (STORAGE_REPORTS_DIR / app/storage/reports by default — see
 * src/lib/reports/generate.ts), never an absolute path, so moving the
 * storage root doesn't invalidate existing rows.
 */
export const reports = pgTable("reports", {
  id: uuid("id").primaryKey().defaultRandom(),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  crawlJobId: uuid("crawl_job_id")
    .notNull()
    .references(() => crawlJobs.id, { onDelete: "cascade" }),
  format: varchar("format", { length: 16 }).notNull(),
  healthScore: integer("health_score"),
  generatedAt: timestamp("generated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  filePath: text("file_path").notNull(),
});
